import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { UseOrganizationChartCollapsedChangeEvent, UseOrganizationChartExposes, UseOrganizationChartProps, UseOrganizationChartSelectionChangeEvent, UseOrganizationChartState } from '@primereact/types/headless/organizationchart';
/**
 * Defines passthrough(pt) options type in OrganizationChart component.
 */
export type OrganizationChartRootPassThroughType<E> = PassThroughType<OrganizationChartRootInstance, E>;
/**
 * Defines passthrough(pt) options of OrganizationChart component.
 */
export interface OrganizationChartRootPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: OrganizationChartRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in OrganizationChart component.
 */
export interface OrganizationChartRootProps extends BaseComponentProps<OrganizationChartRootInstance, UseOrganizationChartProps, OrganizationChartRootPassThrough> {
}
/**
 * Defines valid state in OrganizationChart component.
 * @extends UseOrganizationChartState
 */
export interface OrganizationChartRootState extends UseOrganizationChartState {
}
/**
 * Defines the methods and properties exposed by OrganizationChart component.
 * @extends UseOrganizationChartExposes
 */
export interface OrganizationChartRootExposes extends UseOrganizationChartExposes {
    /**
     * The state of the OrganizationChart component.
     */
    state: OrganizationChartRootState;
}
/**
 * Instance of OrganizationChart component.
 */
export type OrganizationChartRootInstance = ComponentInstance<OrganizationChartRootProps, OrganizationChartRootState, OrganizationChartRootExposes>;
/**
 * Event re-exported from the headless layer so consumers can import it from the
 * primitive/UI barrel instead of reaching into headless. Mirrors `UseOrganizationChartCollapsedChangeEvent`.
 */
export interface OrganizationChartCollapsedChangeEvent extends UseOrganizationChartCollapsedChangeEvent {
}
/**
 * Event re-exported from the headless layer so consumers can import it from the
 * primitive/UI barrel instead of reaching into headless. Mirrors `UseOrganizationChartSelectionChangeEvent`.
 */
export interface OrganizationChartSelectionChangeEvent extends UseOrganizationChartSelectionChangeEvent {
}
